enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    case InvalidPath(message: String
    )
    case Configuration(message: String
    )
    case Io(message: String
    )
    case Transport(message: String, retryable: Bool
    )
    case Http(status: UInt16, code: String, message: String, retryable: Bool
    )
    case Integrity(message: String
    )
    case Cancelled






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

