        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .InvalidPath(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Configuration(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Transport(
            message: try FfiConverterString.read(from: &buf),
            retryable: try FfiConverterBool.read(from: &buf)
            )
        case 5: return .Http(
            status: try FfiConverterUInt16.read(from: &buf),
            code: try FfiConverterString.read(from: &buf),
            message: try FfiConverterString.read(from: &buf),
            retryable: try FfiConverterBool.read(from: &buf)
            )
        case 6: return .Integrity(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Cancelled

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {





        case let .InvalidPath(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)


        case let .Configuration(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)


        case let .Io(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)


        case let .Transport(message,retryable):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(retryable, into: &buf)


        case let .Http(status,code,message,retryable):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(retryable, into: &buf)


        case let .Integrity(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)


        case .Cancelled:
            writeInt(&buf, Int32(7))

        }
    }
